-- Usulan contoh untuk demo ke buyer. Opsional, lewati untuk database produksi yang bersih.
-- Jalankan setelah 02_data_awal.sql karena merujuk ID dusun.

begin;

-- usulan
select setval(pg_get_serial_sequence('public."usulan"', 'id'), (select coalesce(max("id"), 1) from "usulan"));

-- riwayat_usulan
select setval(pg_get_serial_sequence('public."riwayat_usulan"', 'id'), (select coalesce(max("id"), 1) from "riwayat_usulan"));

commit;
